class Node;

// Demonstrates using weak_ptr to break a reference cycle
struct Node {
    std::shared_ptr<Node> next;
    std::weak_ptr<Node> prev; // Use weak_ptr for back-pointer
    ~Node() { std::cout << "Node destroyed\n"; }
};

void demonstrate_weak_ptr() {
    auto sp1 = std::make_shared<Node>();
    auto sp2 = std::make_shared<Node>();

    // Create a cycle with shared_ptr (this would leak)
    // sp1->next = sp2;
    // sp2->next = sp1;

    // Break the cycle with weak_ptr
    sp1->next = sp2;
    sp2->prev = sp1; // sp2 now has a non-owning reference to sp1

    // Safely access the observed object
    if (auto locked_prev = sp2->prev.lock()) {
        // locked_prev is a valid shared_ptr, object is alive
        std::cout << "Accessing prev node is safe.\n";
    } else {
        std::cout << "Prev node has been destroyed.\n";
    }

    // Demonstrate expiration
    std::weak_ptr<Node> weak_observer = sp1;
    std::cout << "sp1 use count: " << sp1.use_count() << std::endl; // Count is 1

    sp1 = nullptr; // sp1 and its reference in sp2->prev are gone
    sp2 = nullptr; // This destroys the last object

    if (weak_observer.expired()) {
        std::cout << "The observed node has expired.\n";
    }
}
